def f(k, C):
    memo = {}
    def solve(k, C):
        if (k, C) in memo:
            return memo[(k, C)]
        if C <= 1:
            res = 1
        elif k == 0:
            res = 1
        else:
            res = max(1, solve(k - 1, C) + solve(k - 1, C - 1) + 1)
        memo[(k, C)] = res
        return res

    return solve(k, C)

